
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_lm_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_lm", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.589773699957192e-01, -1.594078596188347e-01, -1.600639802651183e-01, -1.610871228145963e-01, -1.627317951577752e-01, -1.654798990910189e-01, -1.702867383551113e-01, -1.790790459999305e-01, -1.952963548283508e-01, -2.189717262194304e-01, -1.949770593514547e-01, -8.121128740320328e-02, -7.157696354619424e-02, -6.816613439175222e-02, -6.443445799276411e-02, -6.545472475828189e-02, -9.434457135103499e-02, -2.464825147469731e-01, -1.060155380970140e+00, -8.636023452101709e+00]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


